create function private.admin_organization_identity_edit_snapshot_v1(p_org uuid)returns jsonb language sql stable security definer set search_path=pg_catalog,public as $$
 select jsonb_build_object('organization',jsonb_build_object('id',o.id,'row_version',o.row_version,'legal_name',o.legal_name,'country_code',o.country_code,'status',o.status),'identifiers',coalesce((select jsonb_object_agg(i.identifier_type,i.normalized_value::text)from public.organization_identifiers i where i.organization_id=o.id and i.is_active and i.identifier_type in('ICE','IF','RC')),'{}'),'identifier_verification',coalesce((select jsonb_object_agg(i.identifier_type,i.verification_status)from public.organization_identifiers i where i.organization_id=o.id and i.is_active and i.identifier_type in('ICE','IF','RC')),'{}'),'client_case',case when c.id is null then null else jsonb_build_object('id',c.id,'status',c.status,'row_version',c.row_version,'profile_version',c.current_profile_version,'profile_hash',case when p.id is null then null else private.canonical_request_hash(p.profile_data)end,'legal_profile',case when p.id is null then null else jsonb_build_object('legal_form',p.profile_data->>'legal_form','registered_city',p.profile_data->>'registered_city','registered_address',jsonb_strip_nulls(jsonb_build_object('line1',p.profile_data#>'{registered_address,line1}','line2',p.profile_data#>'{registered_address,line2}','postal_code',p.profile_data#>'{registered_address,postal_code}','country_code',p.profile_data#>'{registered_address,country_code}')))end)end)
 from public.organizations o left join public.client_compliance_cases c on c.organization_id=o.id left join public.client_profile_versions p on p.compliance_case_id=c.id and p.version=c.current_profile_version where o.id=p_org
$$;
revoke all on function private.admin_organization_identity_edit_snapshot_v1(uuid)from public,anon,authenticated,service_role;
create function public.get_admin_organization_identity_edit_context_v1(p_organization_id uuid)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,private as $$
declare snapshot jsonb;begin
 if auth.uid()is null or auth.jwt()->>'aal'is distinct from'aal2'or not private.has_platform_role(array['SUPER_ADMIN','MATRICIA_ADMIN'])then raise exception'ADMIN_IDENTITY_EDIT_DENIED'using errcode='42501';end if;
 snapshot:=private.admin_organization_identity_edit_snapshot_v1(p_organization_id);if snapshot is null then raise exception'ORGANIZATION_NOT_FOUND'using errcode='P0002';end if;
 return jsonb_build_object('snapshot',snapshot,'identity_hash',private.canonical_request_hash(snapshot));
end$$;
revoke all on function public.get_admin_organization_identity_edit_context_v1(uuid)from public,anon,authenticated,service_role;
