   next_if:=upper(regexp_replace(btrim(coalesce(p->>''ifNumber'','''')),''[^[:alnum:]]'','''',''g''));next_rc:=upper(regexp_replace(btrim(coalesce(p->>''rcNumber'','''')),''[^[:alnum:]]'','''',''g''));
   if next_if!~''^[0-9]{6,20}$''or length(next_rc)not between 2 and 80 then raise exception''INVALID_ORGANIZATION_FISCAL_IDENTIFIERS''using errcode=''22023'';end if;
