    if new_profile_data#>>''{registered_address,country_code}''is distinct from coalesce(nullif(upper(p->>''country''),''''),o.country_code)then raise exception''LEGAL_ADDRESS_COUNTRY_MISMATCH''using errcode=''23514'';end if;
    profile_changed:=new_profile_data is distinct from prior.profile_data;
   end if;
