    if coalesce(new_profile_data#>>''{registered_address,country_code}'',o.country_code)is distinct from coalesce(nullif(upper(p->>''country''),''''),o.country_code)then raise exception''LEGAL_ADDRESS_COUNTRY_MISMATCH''using errcode=''23514'';end if;
    profile_changed:=new_profile_data->>''legal_form''is distinct from prior.profile_data->>''legal_form''or new_profile_data->>''registered_city''is distinct from prior.profile_data->>''registered_city''or new_profile_data#>>''{registered_address,line1}''is distinct from prior.profile_data#>>''{registered_address,line1}''or coalesce(new_profile_data#>>''{registered_address,line2}'','''')is distinct from coalesce(prior.profile_data#>>''{registered_address,line2}'','''')or coalesce(new_profile_data#>>''{registered_address,postal_code}'','''')is distinct from coalesce(prior.profile_data#>>''{registered_address,postal_code}'','''')or coalesce(new_profile_data#>>''{registered_address,country_code}'',o.country_code)is distinct from coalesce(prior.profile_data#>>''{registered_address,country_code}'',o.country_code)or new_profile_data->>''if_number''is distinct from prior.profile_data->>''if_number''or new_profile_data->>''rc_number''is distinct from prior.profile_data->>''rc_number'';end if;
  end if;
  changed:=coalesce(nullif(p->>''legalName'',''''),o.legal_name)is distinct from o.legal_name or coalesce(nullif(upper(p->>''country''),''''),o.country_code)is distinct from o.country_code or ice is distinct from old_ice or next_if is distinct from old_if or next_rc is distinct from old_rc or profile_changed; if extended_identity and not changed then raise exception''NO_CANONICAL_IDENTITY_CHANGE''using errcode=''22023'';end if; if changed and prior.id is not null and not extended_identity and coalesce(nullif(upper(p->>''country''),''''),o.country_code)is distinct from o.country_code then raise exception''CANONICAL_LEGAL_PROFILE_REVISION_REQUIRED''using errcode=''55000'';end if;');
 if strpos(definition,'   update public.organization_identifiers set verification_status=''PENDING''where organization_id=o.id and identifier_type in(''IF'',''RC'')and is_active;')=0 then raise exception'CANONICAL_IDENTITY_REVISION_PATCH_TARGET_MISSING';end if;
